CREATE proc [dbo].[UspUpdateItem]  @ItemId as int, @SBId as int, @Item as nvarchar(50), @GRId as int, @ItemCode as nvarchar(50), @Type as int, @Yield as decimal(18,2)  as  Declare @IsExist as bit;  set @IsExist = 0;  if @IsExist = 0 begin  Declare @ItemType nvarchar(50); select @ItemType = ItemType from Butchery where id = @Type  update Item set  SBId =@SBId, Item =@Item, GRId =@GRId, ItemCode=@ItemCode, [Type]=@ItemType,Yield = @Yield  where ItemId = @ItemId end  select @IsExist;